<?php
require_once '../includes/auth.php'; require_once '../config/koneksi.php';
$q=trim($_GET['q']??''); $from=trim($_GET['from']??''); $to=trim($_GET['to']??''); $kelasFilter=trim($_GET['kelas']??''); $tingkatFilter=trim($_GET['tingkat']??'');
$where=[]; $types=''; $params=[];
if($q!==''){ $where[]='(p.no_transaksi LIKE ? OR s.nama_siswa LIKE ? OR s.nis LIKE ? OR j.nama_jenis LIKE ?)'; $like="%$q%"; array_push($params,$like,$like,$like,$like); $types.='ssss'; }
if($from!=='' && preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)){ $where[]='p.tanggal_bayar >= ?';$params[]=$from;$types.='s'; }
if($to!=='' && preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)){ $where[]='p.tanggal_bayar <= ?';$params[]=$to;$types.='s'; }
if($kelasFilter!==''){ $where[]='s.kelas = ?';$params[]=$kelasFilter;$types.='s'; }
if(in_array($tingkatFilter,['VII','VIII','IX'],true)){ $where[]="s.kelas LIKE CONCAT(?, '%')";$params[]=$tingkatFilter;$types.='s'; }
$sql='SELECT p.*,s.nama_siswa,s.nis,s.kelas,j.nama_jenis,j.tingkat FROM pembayaran p JOIN siswa s ON s.id_siswa=p.id_siswa JOIN jenis_pembayaran j ON j.id_jenis=p.id_jenis'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY p.tanggal_bayar DESC,p.id_pembayaran DESC';
$st=$conn->prepare($sql); if($params)$st->bind_param($types,...$params);$st->execute();$data=$st->get_result();$rows=$data->fetch_all(MYSQLI_ASSOC);$count=count($rows);$filteredTotal=0;foreach($rows as $row)$filteredTotal+=(float)$row['jumlah'];
$page_title='Pembayaran';$active='pembayaran';$prefix='../';include '../includes/header.php';
?>
<div class="page-heading"><div><h1>Pembayaran</h1><p>Catat transaksi, pantau penerimaan, dan cetak bon kas sebagai bukti pembayaran.</p></div><a href="tambah.php" class="btn btn-primary"><i class="bi bi-plus-lg me-1"></i>Catat Pembayaran</a></div>
<div class="row g-3 mb-3"><div class="col-md-4"><div class="stat-card"><div class="stat-label">Total nominal sesuai filter</div><div class="stat-value" style="font-size:22px"><?= rupiah($filteredTotal) ?></div></div></div><div class="col-md-4"><div class="stat-card"><div class="stat-label">Transaksi ditemukan</div><div class="stat-value"><?= number_format($count) ?></div></div></div><div class="col-md-4"><div class="stat-card"><div class="stat-label">Bukti transaksi</div><div class="text-secondary mt-2">Setiap transaksi dapat dicetak menjadi bon kas siap cetak A5.</div></div></div></div>
<div class="panel"><div class="panel-head"><div><strong>Riwayat Transaksi</strong><div class="text-secondary small mt-1">Cari berdasarkan nomor bon/transaksi, nama atau NIS siswa, dan jenis pembayaran.</div></div></div>
<div class="panel-body border-bottom"><form class="row g-2 align-items-end"><div class="col-lg-3"><label class="form-label">Pencarian</label><input class="form-control" name="q" value="<?= e($q) ?>" placeholder="No. transaksi, nama, NIS..."></div><div class="col-md-4 col-lg-2"><label class="form-label">Tingkat SMP</label><select class="form-select" name="tingkat"><option value="">Semua Tingkat</option><?php foreach(['VII','VIII','IX'] as $t):?><option value="<?= $t ?>" <?= $tingkatFilter===$t?'selected':'' ?>>Kelas <?= $t ?></option><?php endforeach;?></select></div><div class="col-md-4 col-lg-2"><label class="form-label">Nama Kelas</label><select class="form-select" name="kelas"><option value="">Semua Kelas</option><?php $ks=$conn->query("SELECT DISTINCT kelas AS nama_kelas FROM siswa WHERE kelas IS NOT NULL AND kelas<>'' ORDER BY kelas");while($kk=$ks->fetch_assoc()):?><option value="<?= e($kk['nama_kelas']) ?>" <?= $kelasFilter===$kk['nama_kelas']?'selected':'' ?>><?= e($kk['nama_kelas']) ?></option><?php endwhile;?></select></div><div class="col-sm-5 col-lg-2"><label class="form-label">Dari tanggal</label><input class="form-control" type="date" name="from" value="<?= e($from) ?>"></div><div class="col-sm-5 col-lg-2"><label class="form-label">Sampai tanggal</label><input class="form-control" type="date" name="to" value="<?= e($to) ?>"></div><div class="col-sm-2 col-lg-2 d-flex gap-2"><button class="btn btn-primary flex-fill"><i class="bi bi-search"></i> Cari</button><a class="btn btn-light border" href="index.php" title="Reset filter"><i class="bi bi-arrow-counterclockwise"></i></a></div></form></div>
<div class="table-responsive"><table class="table"><thead><tr><th>No. Transaksi</th><th>Tanggal</th><th>Siswa</th><th>Jenis</th><th>Tingkat Biaya</th><th>Metode</th><th>Jumlah</th><th>Aksi</th></tr></thead><tbody>
<?php foreach($rows as $r):?><tr><td><strong><?= e($r['no_transaksi']) ?></strong><div class="text-secondary small">Bon BK-<?= str_pad((string)$r['id_pembayaran'],5,'0',STR_PAD_LEFT) ?></div></td><td><?= date('d/m/Y',strtotime($r['tanggal_bayar'])) ?></td><td><?= e($r['nama_siswa']) ?><div class="text-secondary small">NIS: <?= e($r['nis']) ?> · Kelas <?= e($r['kelas']?:'-') ?></div></td><td><?= e($r['nama_jenis']) ?></td><td><?= e(($r['tingkat']??'Semua Tingkat')==='Semua Tingkat'?'Semua Tingkat':'Kelas '.$r['tingkat']) ?></td><td><span class="badge-soft"><?= e($r['metode_pembayaran']) ?></span></td><td class="fw-bold text-nowrap"><?= rupiah($r['jumlah']) ?></td><td class="text-nowrap"><a class="btn btn-sm btn-primary" target="_blank" rel="noopener" href="cetak.php?id=<?= (int)$r['id_pembayaran'] ?>"><i class="bi bi-printer me-1"></i>Bon Kas</a> <a class="btn btn-sm btn-outline-danger" data-confirm="Yakin menghapus transaksi ini? Data yang dihapus tidak bisa dicetak kembali." href="hapus.php?id=<?= (int)$r['id_pembayaran'] ?>" title="Hapus transaksi"><i class="bi bi-trash"></i></a></td></tr><?php endforeach;?>
<?php if(!$count):?><tr><td colspan="8" class="empty"><i class="bi bi-inbox fs-3 d-block mb-2"></i>Belum ada transaksi yang sesuai dengan pencarian.</td></tr><?php endif;?></tbody></table></div></div>
<?php include '../includes/footer.php';?>
